from taf.ul.kpi_selector.operations.site_reset.classical_site_reset.site_reset_22R2 import SiteReset22R2


class SiteReset22R3(SiteReset22R2):

    def get_kpi(self):
        """
        Gets kpi for site reset operation.
        :return: dictionary with timeout, requirement and operation description for site reset
        :rtype: dict
        """
        use_restrictions = True

        if all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIM", bbmod_types=["ABIO", "ABIN"]),
                    self.bts.number_of_bbmods <= 3,
                    self.bts.setup_mode == "SA"
                ]
        ):
            self.operation_details["Timeout"] = 360
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.19154"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIM", bbmod_types=["ABIO", "ABIN"]),
                    self.bts.number_of_bbmods <= 6,
                    self.bts.setup_mode == "NSA"
                ]
        ):
            self.operation_details["Timeout"] = 720
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.19163"

        else:
            return super(SiteReset22R3, self).get_kpi()

        if use_restrictions:
            self.operation_details["Timeout"] += self.restrictions.use_restrictions_from_OM_GEN_SFS_PERF_CAP_13441()

        return self.operation_details
